def format_target_spec_trace(scope, root_error, width=TRACE_WIDTH, depth=0,
    prev_target=_MISSING, last_branch=True):
    stack = _unpack_stack(scope)
    lines = []
    indent = ' ' * depth

    prev_target = _MISSING

    for i, (frame_scope, spec, target, error, branches) in enumerate(stack):
        # Print target if it changed
        if target is not prev_target:
            target_repr = _format_trace_value(target, width - len(indent) - len(' - Target: '))
            lines.append(f'{indent} - Target: {target_repr}')
            prev_target = target

        spec_repr = _format_trace_value(spec, width - len(indent) - len(' - Spec: '))

        if branches:
            # This is a branching spec
            lines.append(f'{indent} + Spec: {spec_repr}')

            for branch_scope in branches:
                branch_stack = _unpack_stack(branch_scope, only_errors=False)
                if not branch_stack:
                    continue

                # Get the first spec in the branch
                b_scope, b_spec, b_target, b_error, b_branches = branch_stack[0]
                b_spec_repr = _format_trace_value(b_spec, width - len(indent) - len(' |\\ Spec: '))
                lines.append(f'{indent} |\\ Spec: {b_spec_repr}')

                # If there are more items in this branch
                for j in range(1, len(branch_stack)):
                    bb_scope, bb_spec, bb_target, bb_error, bb_branches = branch_stack[j]
                    if bb_branches:
                        sub_lines = format_target_spec_trace(bb_scope, root_error, width=width, depth=depth+1, last_branch=False)
                        # indent these lines with branch prefix
                        for line in sub_lines.split('\n'):
                            if line:
                                lines.append(f'{indent} |{line[depth+1:]}')
                    else:
                        bb_spec_repr = _format_trace_value(bb_spec, width - len(indent) - len(' || Spec: '))
                        lines.append(f'{indent} || Spec: {bb_spec_repr}')

                # Print the error for this branch if it failed
                b_last = branch_stack[-1]
                if b_last[3] is not None and b_last[3] is root_error:
                    pass  # error will be printed at the end
                elif b_last[3] is not None:
                    err_repr = f'{type(b_last[3]).__module__}.{type(b_last[3]).__name__}: {b_last[3].get_message() if hasattr(b_last[3], "get_message") else str(b_last[3])}'
                    lines.append(f'{indent} |X {err_repr}')
        else:
            lines.append(f'{indent} - Spec: {spec_repr}')

    return '\n'.join(lines)
